import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 14
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    )

    records = list(reader)
    header_index = None
    first_nonblank = None

    for index, record in enumerate(records):
        if not any(value.strip() for value in record):
            continue
        if first_nonblank is None:
            first_nonblank = index

        # Look for the indicated single header row after any preamble.
        if len(record) == expected_width:
            labels = [value.strip() for value in record]
            if len(set(labels)) == expected_width and all(
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", label)
                for label in labels
            ):
                header_index = index
                break

    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index].copy()
    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))

    # Keep overflow cells in extra columns rather than discarding or merging them.
    used_names = set(columns)
    next_number = 1
    while len(columns) < width:
        name = f"_extra_{next_number}"
        next_number += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
